    EXPECT(HIT(ax, UPD_ROW_Y0 + 12) == 9, "no page-up arrow on a two-page list (%d)", HIT(ax, UPD_ROW_Y0 + 12));
    TAP(ax, UPD_ROW_Y0 + UPD_ROWS_PER * UPD_ROW_H - 20);              /* page down */
