    for (int k = 0; k < 8 && update_page() != UPD_PG_OFFER; k++) { net_sim_advance(0.5f); update_tick(0.5f); update_touch(PG_X(bl), PG_Y(yb), true); }
    EXPECT(update_page() == UPD_PG_OFFER, "no offer under the resting finger (page %d)", update_page());
