        tank.night = false; for (int k = 0; k < 30; k++) { tank.clock += 0.04f; render_tank(&tank, fb, TANK_W); }
        int lb1, lr1; int64_t lu1; render_grass_loop_prof(&ln0, &lb1, &lu1, &lr1);
