              tank.fish[0].x = fx0; tank.fish[0].y = fy0; for (int k = 0; k < 25 * 60; k++) tank_tick(&tank, 1.0f / 60, advisor_rules); tank.cr_poke = 0; tank.cr_startle_cool = 0;
