                  char line[200]; int lc = 0; 
                  for (float g = 30; g <= 160; g += 10) { w = crab_race(&base, g, &edge); lc += snprintf(line + lc, sizeof line - lc, "%s", w == 1 ? "C" : w == 2 ? "s" : "-"); }
