#include "r2_marker.inc"     /* (round 2, the shelf's paid marker: --selftest-r2-marker) */
#include "farm.inc"          /* (0.4.1 audit, reviewer progression: --selftest-farm, the money loops) */
#include "farm2.inc"         /* (round 2: --selftest-farm2) */
